//--------------------------------------------------------------------------//

void dei_ss_hood_close( void )
{	
	if( get_ss_arm() && !get_ss_trigger() && get_ss_hood_bypass()) {
			set_ss_hood_bypass( FALSE );	

			if( get_ss_door_bypass() || get_ss_trunk_bypass() ) {            
			dei_led_flash( DEI_SS_LED_ZONE_BYPASS , LED_ENABLE);								
      }
    else {
      dei_led_flash( DEI_LED_ARM , LED_ENABLE); 
      }	
		}
	if( get_zone_bypass_status() ) return ; 

	set_ss_hood_bypass( FALSE );
}


//--------------------------------------------------------------------------//

void dei_ss_hood_open( void )
{
	if( get_zone_bypass_status() ) return ; 
	
    if( get_ss_arm() && !get_ss_valet() )
	{
		dei_ss_trigger_start( DEI_SS_TRIGGER_ZONE_HOOD ) ;        
	}    
}	

